// number
let num1 = 10;
let num2 = 20.5;
let num3 = -5;
let num4 = 0xFF; // hexadecimal
let num5 = 0b1010; // binary
let num6 = 0o77; // octal  
let num7 = 1e6; // exponential notation
let num8 = NaN; // Not a Number
let num9 = Infinity; // Infinity
let num10 = -Infinity; // Negative Infinity
// string
let str1 = "Hello, World!";
let str2 = 'TypeScript is great!';
let str3 = `The sum of 5 and 10 is ${5 + 10}.`; // template literal  
let str4 = "This is a multi-line string.\nIt spans multiple lines.";
// boolean
let isTrue = true;
let isFalse = false;
// null and undefined
let nullValue = null;
let undefinedValue = undefined;
let unde1 = undefined;
// 리터널 타입
// 리터널 은 값으로 타입을 지정하는 것
let literal1 = "Hello";
let literal2 = 42;
let literal3 = true;
export {};
